    "time" time without time zone,
    team1_id bigint NOT NULL,
    team2_id bigint NOT NULL,
    score1 integer,
    score2 integer,
    status character varying(20) DEFAULT 'SCHEDULED'::character varying NOT NULL,
    CONSTRAINT chk_match_scores_consistency CHECK ((((score1 IS NULL) AND (score2 IS NULL)) OR ((score1 IS NOT NULL) AND (score2 IS NOT NULL)))),
